// INTELLIGENT TASK PROCESSOR WITH PROPER LOGIC
const tasks = $input.first().json.result || [];
console.log(`🔍 Processing ${tasks.length} Kanboard tasks`);

// Find master Due Diligence tasks only
let validTasks = [];
for (const task of tasks) {
  const title = task.title ? task.title.toString() : '';
  const description = task.description ? task.description.toString() : '';

  // EXACT requirement: "Due Diligence: [Company Name]" with website in description
  if (title.toLowerCase().includes('due diligence:') && description.includes('http')) {
    const companyName = title.replace(/due diligence:\s*/i, '').trim();
    const websiteMatch = description.match(/https?:\/\/[^\s]+/);
    const websiteUrl = websiteMatch ? websiteMatch[0] : null;

    if (companyName && websiteUrl) {
      validTasks.push({
        kanboard_id: task.id,
        title: title,
        description: description,
        company_name: companyName,
        website_url: websiteUrl,
        project_id: task.project_id || 1
      });
    }
  }
}

console.log(`📋 Found ${validTasks.length} valid Due Diligence tasks`);

if (validTasks.length === 0) {
  console.log('ℹ️ No Due Diligence tasks found - workflow completed');
  throw new Error('No Due Diligence tasks found');
}

// Return first task for processing
const taskToProcess = validTasks[0];
console.log(`🎯 Processing: ${taskToProcess.company_name}`);

return {
  json: {
    ...taskToProcess,
    found_tasks_count: validTasks.length,
    workflow_action: 'PROCESS_COMPANY'
  }
};

// KNOWLEDGE BASE AND WORKFLOW CONTROLLER
const taskData = $('Find Valid DD Tasks').first().json;
const attachments = $('Get Task PDFs').first().json.result || [];

// Process FinBERT data
let finbertData = null;
try {
  const finbertResponse = $('Run FinBERT Analysis').first();
  if (finbertResponse && finbertResponse.json) {
    finbertData = finbertResponse.json;
    console.log('✅ FinBERT analysis successful');
  }
} catch (error) {
  console.log(`⚠️ FinBERT error: ${error.message}`);
}

// Define all 20 sections in exact order
const ALL_SECTIONS = [
  { name: "Introduction & Engagement Context", index: 1, description: "Context, objectives, and scope of the due diligence engagement" },
  { name: "Methodology & Reliability Levels", index: 2, description: "Analytical approach, data sources, and reliability assessment methodology" },
  { name: "Company Overview", index: 3, description: "Company history, leadership team, ownership structure, mission, and operational scale" },
  { name: "Business Model & Unit Economics", index: 4, description: "Revenue streams, cost structure, pricing strategy, and unit economics analysis" },
  { name: "Products & Technology", index: 5, description: "Product portfolio, technology stack, R&D capabilities, and competitive differentiation" },
  { name: "Target Market & Competitive Set", index: 6, description: "Market segments, customer base, competitive landscape, and market positioning" },
  { name: "Financials", index: 7, description: "Multi-year financial statements analysis, reconciliation, and recomputation" },
  { name: "Cash, Burn, Runway", index: 8, description: "Cash position, burn rate analysis, and runway calculations" },
  { name: "Revenue Quality & Client Cohorts", index: 9, description: "Revenue composition, client concentration, retention, and cohort analysis" },
  { name: "Partnerships & Ecosystem", index: 10, description: "Strategic partnerships, ecosystem integration, and channel relationships" },
  { name: "Intellectual Property", index: 11, description: "Patent portfolio, trademarks, copyrights, and IP strategy" },
  { name: "Legal & Regulatory", index: 12, description: "Legal structure, compliance status, regulatory risks, and litigation" },
  { name: "Governance & Board Effectiveness", index: 13, description: "Board composition, governance practices, and decision-making processes" },
  { name: "Capital Structure & Dilution", index: 14, description: "Equity structure, debt analysis, and potential dilution scenarios" },
  { name: "Risk Matrix & Mitigations", index: 15, description: "Key risk identification, assessment, and mitigation strategies" },
  { name: "Gaps, Uncertainties & Disclaimers", index: 16, description: "Data gaps, analytical uncertainties, and disclosure disclaimers" },
  { name: "Scenario Analysis", index: 17, description: "Multiple scenario modeling and sensitivity analysis" },
  { name: "Strategic Options", index: 18, description: "Strategic alternatives and growth pathways for the company" },
  { name: "Recommendations & Next Steps", index: 19, description: "Actionable recommendations and proposed next steps" },
  { name: "Source Map & Integrity Log", index: 20, description: "Data sources mapping and integrity verification log" }
];

console.log(`📊 Knowledge Base Summary:`);
console.log(`  - Company: ${taskData.company_name}`);
console.log(`  - Website: ${taskData.website_url}`);
console.log(`  - PDFs: ${attachments.length} files`);
console.log(`  - FinBERT: ${finbertData ? 'Available' : 'Failed'}`);
console.log(`  - Sections: ${ALL_SECTIONS.length} to process`);

// This is where we'll use databases instead of Kanboard storage
return {
  json: {
    ...taskData,
    attachments: attachments,
    finbert_data: finbertData,
    all_sections: ALL_SECTIONS,
    knowledge_base: {
      company_name: taskData.company_name,
      website_url: taskData.website_url,
      pdf_files: attachments.map(a => a.name || 'unknown'),
      financial_analysis: finbertData,
      total_sources: attachments.length + 1 + (finbertData ? 1 : 0)
    },
    next_action: 'DATABASE_SETUP'
  }
};
